function applyDiscount(cart, user) {
  // Increment loyalty points by 1
  user.points += 1;
  // Loop over the items in the cart
  for (const item of cart.items) {
    // Multiply price by quantity and store it
    item.subtotal = item.price * item.quantity;
  }
  // const legacyRate = 0.05;
  // TODO: handle expired coupons
  if (user.tier === 'gold') {
    cart.total *= 0.9;
  }
  return cart;
}
